import{_ as n,o as e,c as l,a2 as i,j as a,a as s}from"./chunks/framework.DxqK4cCD.js";const $=JSON.parse('{"title":"Multi-Modal Hyper-Graph Fusion for Low-Light Crowd Counting","description":"提出多模态超图融合与可变形稀疏注意力网络，首次系统性地解决了低光环境下的人群计数难题。","frontmatter":{"title":"Multi-Modal Hyper-Graph Fusion for Low-Light Crowd Counting","description":"提出多模态超图融合与可变形稀疏注意力网络，首次系统性地解决了低光环境下的人群计数难题。","date":"2026-06-18","arxivId":"2606.18566","domain":"计算机视觉 · 人工智能 · 计算机图形学","level":"基础","tags":["低光人群计数","多模态融合","超图学习","稀疏注意力","计算机视觉"],"originalUrl":"https://arxiv.org/abs/2606.18566","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-06-18/2606.18566.md"},"headers":[],"relativePath":"papers/daily/2026-06-18/2606.18566.md","filePath":"papers/daily/2026-06-18/2606.18566.md","lastUpdated":1786541753000}'),r={name:"papers/daily/2026-06-18/2606.18566.md"};function p(h,t,o,d,g,E){return e(),l("div",null,[...t[0]||(t[0]=[i("",15),a("ul",null,[a("li",null,[a("strong",null,"多模态特征提取"),s("：首先，使用一个共享的骨干网络（如VGG-16或ResNet-50）从输入的低光RGB图像中提取多尺度特征。同时，通过一个预训练的深度估计网络（如MiDaS）和Canny边缘检测器分别生成深度图和边缘图。然后，使用三个独立的轻量级特征提取分支（每个分支由几个卷积层组成）将RGB、深度和边缘信息分别映射到统一的特征空间，得到三种模态的特征图 $F_{rgb} \\in \\mathbb{R}^{H \\times W \\times C}$、$F_{depth} \\in \\mathbb{R}^{H \\times W \\times C}$ 和 $F_{edge} \\in \\mathbb{R}^{H \\times W \\times C}$。")]),a("li",null,[a("strong",null,"多模态超图融合模块"),s("：该模块是核心创新之一。首先，将三种模态特征图上的每个空间位置视为一个超图节点，所有节点构成节点集 $V$。然后，通过一个动态超边生成器（Dynamic Hyperedge Generator），基于节点特征之间的相似性（如余弦相似度）或空间邻近性，自适应地为每个节点构建超边（Hyperedge）。一个超边可以连接任意数量的节点，从而建模高阶关系。具体地，对于每个节点 $v_i$，其对应的超边 $e_i$ 包含与 $v_i$ 特征最相似的 $K$ 个节点（可能来自不同模态）。接着，执行超图消息传递：首先聚合超边内所有节点的信息，得到超边表示 $h_e$；然后，将超边表示更新到每个节点上。这个过程可以形式化为：$v_i^{(t+1)} = \\sigma(\\sum_{e \\in \\mathcal{E}(v_i)} W_e \\cdot \\text{AGG}"),a("em",{fusion:""},"{j \\in e}(v_j^{(t)}))$，其中 $\\mathcal{E}(v_i)$ 是包含节点 $v_i$ 的超边集合，$\\text{AGG}$ 是聚合函数（如平均或最大池化），$W_e$ 是可学习的权重矩阵。经过多轮消息传递后，得到融合了高阶互补关系的多模态特征 $F"),s("$。")]),a("li",null,[a("strong",null,"可变形矩形稀疏注意力模块"),s("：该模块旨在实现自适应稀疏计算。首先，通过一个轻量级的锚点感知子网络（Anchor-Aware Subnet），从融合特征 $F_{fusion}$ 中预测一组稀疏的锚点（Anchor Points）位置，这些锚点通常位于人群密集区域。然后，对于每个锚点，通过一个可变形矩形采样器（Deformable Rectangular Sampler），学习一个矩形窗口的偏移量（Offset）和缩放量（Scale），从而自适应地确定一个覆盖关键区域的矩形感受野。最后，仅在由这些自适应矩形窗口覆盖的区域内执行多头自注意力（Multi-Head Self-Attention, MSA）计算，而窗口之外的区域则被忽略或仅进行简单的线性变换。这大大减少了注意力机制的计算复杂度，从 $O(H^2W^2)$ 降低到 $O(N \\cdot R^2)$，其中 $N$ 是锚点数量，$R$ 是矩形窗口的平均尺寸。")]),a("li",null,[a("strong",null,"密度图回归"),s("：将经过超图融合和稀疏注意力增强后的特征图输入到一个密度图回归头（通常由几个卷积层和上采样层组成），生成最终的人群密度图（Density Map）。对密度图进行逐像素求和，即可得到总人数估计。")]),a("li",null,[a("strong",null,"损失函数"),s("：训练过程中，使用标准的欧几里得距离损失（Euclidean Distance Loss）来监督密度图的生成，即 $L = \\frac{1}{N} \\sum_{i=1}^{N} ||D_{pred}(i) - D_{gt}(i)||^2$，其中 $D_{pred}$ 和 $D_{gt}$ 分别是预测密度图和真实密度图。")])],-1),i("",41)])])}const c=n(r,[["render",p]]);export{$ as __pageData,c as default};
